update public.content_variants set body_id = $json${"type":"image_interpretation","answer":"Portofolio optimal untuk setiap tingkat risiko","options":["Pengembalian tertinggi tanpa memandang risiko","Portofolio optimal untuk setiap tingkat risiko","Portofolio paling aman","Ambang pengembalian yang dijamin"],"question":"[GAMBAR: Sebuah diagram pencar menunjukkan risiko (volatilitas) pada sumbu X dan pengembalian pada sumbu Y. Beberapa saham Indonesia dipetakan. Sebuah garis diagonal menunjukkan garis batas efisien.]\n\nApa yang diwakili oleh garis batas efisien?","difficulty":"intermediate","parameters":{"image_description":"Sebuah diagram pencar menunjukkan risiko (volatilitas) pada sumbu X dan pengembalian pada sumbu Y. Beberapa saham Indonesia dipetakan. Sebuah garis diagonal menunjukkan garis batas efisien."},"explanation":"Garis batas efisien mewakili portofolio yang menawarkan pengembalian tertinggi yang diharapkan untuk tingkat risiko tertentu."}$json$::jsonb where id = 'dea1899b-1cb0-4f75-b2f4-b8cd70b7c175';
