update public.content_variants set body_id = $json${"type":"scenario","answer":"Mengumpulkan lebih banyak informasi","options":["Bertindak segera","Mengumpulkan lebih banyak informasi","Konsultasi dengan profesional","Tidak melakukan apa-apa"],"question":"Seorang teman menawarkan pengembalian bulanan 50% yang dijamin pada sebuah investasi. Apa yang Anda lakukan? Apa langkah rasional berikutnya?","difficulty":"beginner","parameters":{"scenario_text":"Seorang teman menawarkan pengembalian bulanan 50% yang dijamin pada sebuah investasi. Apa yang Anda lakukan?"},"explanation":"Dalam skenario ini, mengumpulkan lebih banyak informasi mewakili pendekatan yang paling seimbang dan terinformasi dalam pengambilan keputusan keuangan."}$json$::jsonb where id = 'e79d30a6-c6b1-407b-97a7-cf054f76c9f7';
update public.content_variants set body_id = $json${"type":"scenario","answer":"Berinvestasi secara bertahap dari waktu ke waktu","options":["Berinvestasi sekaligus","Berinvestasi secara bertahap dari waktu ke waktu","Menunggu waktu yang sempurna","Tidak pernah berinvestasi"],"question":"Sebuah aplikasi fintech menawarkan 8% pada deposito tetapi tidak berlisensi OJK. Sebuah bank menawarkan 4% dengan lisensi OJK. Bandingkan risikonya. Apa yang akan dilakukan oleh orang yang melek finansial?","difficulty":"intermediate","parameters":{"scenario_text":"Sebuah aplikasi fintech menawarkan 8% pada deposito tetapi tidak berlisensi OJK. Sebuah bank menawarkan 4% dengan lisensi OJK. Bandingkan risikonya."},"explanation":"Dalam skenario ini, berinvestasi secara bertahap dari waktu ke waktu mewakili pendekatan yang paling seimbang dan terinformasi dalam pengambilan keputusan keuangan."}$json$::jsonb where id = 'e9646e1c-457d-44b2-b339-6e2b78be3f73';
update public.content_variants set body_id = $json${"type":"calculation","answer":"20","question":"Sebuah saham diperdagangkan pada Rp 20.000 dengan EPS Rp 1.000. Berapa rasio P/E-nya?","difficulty":"advanced","parameters":{"hint":"Bagilah harga saham dengan laba per saham."},"explanation":"P/E = Harga per saham / Laba per saham = 20.000 / 1.000 = 20."}$json$::jsonb where id = 'e9728eee-be1a-4ccd-ac2c-908aa1d13136';
