update public.content_variants set body_id = $json${"type":"decision_tree","answer":"Status lisensi OJK","options":["Grafik kinerja masa lalu","Status lisensi OJK","Jumlah anggota dalam grup mereka","Foto profil mereka"],"question":"Skenario Pohon Keputusan:\n\nSeorang 'penasihat keuangan' menghubungi Anda di WhatsApp menawarkan akses eksklusif ke dana dengan 'pengembalian bulanan 25% yang dijamin'.\n\nTanda bahaya pertama yang harus diperiksa?","difficulty":"intermediate","parameters":{"full_tree":{"stages":[{"next":{"next":{"correct":"Peringatkan teman dan keluarga","options":["Abaikan dan lanjutkan","Peringatkan teman dan keluarga","Posting tentang itu di media sosial","Hadapi penipu"],"question":"Untuk melindungi orang lain, tindakan terbaik?"},"correct":"Laporkan ke OJK dan blokir","options":["Investasikan sejumlah kecil untuk menguji","Laporkan ke OJK dan blokir","Minta diskon biaya masuk","Ajak teman untuk bergabung"],"question":"Mereka tidak memiliki lisensi OJK tetapi menunjukkan 'bukti' pembayaran kepada orang lain. Apa yang harus dilakukan sekarang?"},"correct":"Status lisensi OJK","options":["Grafik kinerja masa lalu","Status lisensi OJK","Jumlah anggota dalam grup mereka","Foto profil mereka"],"question":"Tanda bahaya pertama yang harus diperiksa?"}],"scenario":"Seorang 'penasihat keuangan' menghubungi Anda di WhatsApp menawarkan akses eksklusif ke dana dengan 'pengembalian bulanan 25% yang dijamin'."}},"explanation":"Jalur yang benar: Status lisensi OJK. Ini mewakili keputusan yang paling bijaksana secara finansial pada tahap ini."}$json$::jsonb where id = 'eb83f5ad-68c1-41ab-a689-35cae8bbe52d';
